# Look of the app: one accent colour (the blue of the plots), a near-white page, one sans-serif face, small labels,
# square-ish corners and no shadows, digits that line up in tables, and a hint in empty plot areas.

electrofast_theme = function() {
  # local = TRUE downloads the font files in R, which R cannot do inside a browser (Shinylive, os "emscripten"); there the page loads them
  font = tryCatch(bslib::font_google("Source Sans 3", local = !identical(R.version$os, "emscripten")), error = function(e) NULL)
  bs_theme(version = 5,
    bg = "#FBFBFA", fg = "#1F2328", primary = "#1A6FDF", secondary = "#5B6470",
    base_font = if (is.null(font)) bslib::font_collection("Segoe UI", "Helvetica Neue", "Arial", "sans-serif") else
      bslib::font_collection(font, "Segoe UI", "Arial", "sans-serif"),
    font_scale = 0.92, "border-radius" = "3px", "border-radius-lg" = "4px", "border-radius-sm" = "2px",
    "navbar-light-bg" = "#FFFFFF", "bslib-sidebar-bg" = "#F3F4F6") |>
    bs_add_rules("
      .navbar { border-bottom: 1px solid #E3E5E8; }
      .navbar-brand { font-weight: 700; letter-spacing: 0.01em; }
      .card, .bslib-card { box-shadow: none !important; border-color: #E3E5E8; }
      .bslib-sidebar-layout { --_sidebar-bg: #F3F4F6; --bslib-sidebar-bg: #F3F4F6; --_sidebar-border: 1px solid #E3E5E8; }
      .bslib-sidebar-layout > .sidebar, .bslib-sidebar-layout > aside.sidebar { background-color: #F3F4F6 !important; }
      .bslib-sidebar-layout > .sidebar > .sidebar-content { gap: 0.35rem !important; }
      .bslib-sidebar-layout > .sidebar .form-group { margin-bottom: 0.35rem !important; }
      .sidebar .control-label, .sidebar label { font-size: 0.82rem; font-weight: 600; color: #3A4048; margin-bottom: 0.2rem; }
      .sidebar .help-block, .sidebar .form-text { font-size: 0.78rem; color: #6A717B; line-height: 1.35; margin-top: 0.1rem; }
      .sidebar .shiny-input-container { margin-bottom: 0.55rem; }
      .sidebar .shiny-input-container .progress { margin-top: 0.3rem; margin-bottom: 0.2rem; height: 1.05rem; font-size: 0.72rem; }
      .sidebar .form-control, .sidebar .selectize-input { font-size: 0.88rem; padding-top: 0.3rem; padding-bottom: 0.3rem; min-height: 0; }
      .sidebar .btn { font-size: 0.85rem; }
      .sidebar .btn-default, .sidebar .shiny-download-link { padding: 0.25rem 0.6rem; border-color: #C9CED4; background: #FFFFFF; color: #2B3138; }
      .card-header { background: #FFFFFF; }
      .card-header:not(:has(.nav)) { font-size: 0.8rem; font-weight: 600; text-transform: uppercase; letter-spacing: 0.04em; color: #5B6470; }
      .nav-tabs .nav-link, .navbar .nav-link { font-size: 0.92rem; }
      .card-body > h6 { font-size: 0.8rem; text-transform: uppercase; letter-spacing: 0.04em; color: #5B6470; margin-top: 0.8rem; }
      table td, table th { font-variant-numeric: tabular-nums; }
      table.table { font-size: 0.86rem; }
      h5, h6 { font-weight: 600; }
      .shiny-plot-output:not(:has(img)) { background: #F7F8F9; border: 1px dashed #D5D9DE; border-radius: 3px; position: relative; }
      .shiny-plot-output:not(:has(img))::before { content: 'Load files in the sidebar to see the plot here.';
        position: absolute; top: 50%; left: 50%; transform: translate(-50%, -50%); color: #8A919A; font-size: 0.9rem; }
    ") |>
    bs_add_rules(technique_icons())
}

# Small line drawings of the curve each technique gives, shown before the tab names (CSS only, matched on the tab
# names, so no tab code changes). Same blue as the plots.
technique_icons = function(col = "#1A6FDF") {
  path = c(
    "Cyclic voltammetry" = "M2 11 C5 11 6 4 8 6 C9 7 10 8 14 8 M14 8 C11 9 10 12 8 10 C6 8 5 12 2 11",
    "Peaks and kinetics" = "M2 11 C5 11 6 4 8 6 C9 7 10 8 14 8 M14 8 C11 9 10 12 8 10 C6 8 5 12 2 11",
    "Linear sweep voltammetry" = "M2 13 C8 13 9 9 14 3",
    "Pulse voltammetry (DPV, SWV)" = "M2 12 L5 12 C7 12 7 4 8 4 C9 4 9 12 11 12 L14 12",
    "Potentiometry" = "M2 13 L14 3",
    "Equations" = "M3 4 L13 4 M3 8 L13 8 M3 12 L9 12",
    "CV: peaks, scan rate, kinetics" ="M2 11 C5 11 6 4 8 6 C9 7 10 8 14 8 M14 8 C11 9 10 12 8 10 C6 8 5 12 2 11",
    "Surface area (CV peak)" = "M2 12 L5 12 C7 12 7 4 8 4 C9 4 9 12 11 12 L14 12",
    "ECSA" = "M2 12 L5 12 C7 12 7 4 8 4 C9 4 9 12 11 12 L14 12",
    "Double-layer capacitance" = "M3 5 L13 5 L13 11 L3 11 Z",
    "Tafel" = "M2 13 L6 9 L14 3",
    "DPV / SWV calibration" = "M2 12 L5 12 C7 12 7 4 8 4 C9 4 9 12 11 12 L14 12",
    "Open-circuit potential" = "M2 5 C5 9 8 8 14 8",
    "Chronoamperometry" = "M2 14 L4 14 L4 3 C5 9 8 11 14 12",
    "Chronocoulometry" = "M2 14 L4 14 L4 10 C6 6 9 5 14 4",
    "Chronopotentiometry" = "M2 11 C6 10 8 9 9 7 C10 5 10 3 14 3",
    "Rotating disk (Levich, Koutecky-Levich)" = "M2 12 C7 12 7 4 14 4",
    "RRDE" = "M2 12 C7 12 7 4 14 4 M2 14 C7 14 7 9 14 9",
    "Impedance (EIS)" = "M2 13 A4 4 0 0 1 10 13 L14 8",
    "ISE calibration" = "M2 13 L14 3",
    "ISE" = "M2 13 L14 3",
    "Selectivity" = "M2 6 L6 6 L14 13",
    "Precision" = "M2 8 L14 8 M5 6 L5 10 M8 5 L8 11 M11 6 L11 10",
    # Sensor performance (Selectivity and Precision share the drawings above with the Potentiometry tabs)
    "Sensitivity" = "M2 2 L2 14 L14 14 M4 12 L13 4",
    "Specificity" = "M4 14 L4 3 M8 14 L8 11 M12 14 L12 12",
    "Stability" = "M2 4 L14 6 M2 10 L4 10 M6 10 L8 10 M10 10 L12 10",
    "Speed" = "M2 13 L5 13 C6 5 8 4 14 4",
    # top bar
    "Cell diagram" = "M4 3 L4 13 L12 13 L12 3 M4 8 L12 8 M7 3 L7 10",
    "Report" = "M4 2 L10 2 L13 5 L13 14 L4 14 Z M10 2 L10 5 L13 5 M6 8 L11 8 M6 11 L11 11",
    "Guide" = "M2 4 L7 3 L8 4 L9 3 L14 4 L14 13 L9 12 L8 13 L7 12 L2 13 Z M8 4 L8 13",
    "About" = "M8 1.5 A6.5 6.5 0 1 1 7.99 1.5 M8 7 L8 11.5 M8 4.6 L8 4.9",
    "QC charts" = "M2 3 L14 3 M2 13 L14 13 M2 8 L5 6 L8 10 L11 7 L14 9")
  svg = function(d) paste0("url(\"data:image/svg+xml,", utils::URLencode(sprintf(
    "<svg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 16 16' width='16' height='16'><path d='%s' fill='none' stroke='%s' stroke-width='1.5' stroke-linecap='round' stroke-linejoin='round'/></svg>", d, col), reserved = TRUE), "\")")
  paste(sprintf(".nav-link[data-value=\"%1$s\"]::before, .dropdown-item[data-value=\"%1$s\"]::before, .dropdown-toggle[data-value=\"%1$s\"]::before { content: %2$s; display: inline-block; width: 16px; height: 16px; margin-right: 6px; vertical-align: -3px; }",
                names(path), vapply(path, svg, "")), collapse = "\n")
}

# The name in the top bar, with a small cyclic voltammogram before it
electrofast_brand = function() tags$span(
  HTML("<svg viewBox='0 0 16 16' width='22' height='22' style='vertical-align:-5px;margin-right:6px'><path d='M2 11 C5 11 6 4 8 6 C9 7 10 8 14 8 M14 8 C11 9 10 12 8 10 C6 8 5 12 2 11' fill='none' stroke='#1A6FDF' stroke-width='1.6' stroke-linecap='round'/></svg>"),
  "ElectroFast")

# Possible causes for an ISE calibration session: the signs the app already measures, checked day by day, then combined
# into patterns with what to check. These are prompts for the user, not diagnoses: the same sign can have several causes.
# The cut-offs are this app's defaults, not published standards; the user can change them (th).
#   slope      % of the Nernstian slope over the fit range (default: flagged below 90 or above 110)
#   low end    slope over the three lowest fitted standards / slope over the whole fit (below 0.6)
#   background b of the day / the lowest b of all days, background-corrected fit (above 3)
#   check      end reading minus start reading of the check standard, X then Z (beyond 5 mV)
#   scatter    R2 of the fit (below 0.98)
#   settling   share of fitted standards still drifting at the reading time, Reading time tab rule (above 20%)
diagnose_defaults = list(slope_lo = 90, slope_hi = 110, low_end = 0.6, background = 3, drift_mV = 5, r2 = 0.98, unsettled = 0.2)

diagnose_ise = function(pts, res, bg = NULL, settle = NULL, x = "neg_log_a", read_s = 120, th = diagnose_defaults) {
  days = res$per_day$day
  low_ratio = vapply(days, function(dd) {
    p = pts[pts$day == dd & pts$fit & is.finite(pts$E_mV), ]; p = p[order(p$conc_M), ]
    if (nrow(p) < 5) return(NA_real_)
    # same convention as calibrate(): the plain coefficient of E against the chosen axis, so the ratio is sign-free
    lo = utils::head(p, 3); s_lo = unname(stats::coef(stats::lm(lo$E_mV ~ lo[[x]]))[2])
    s_lo / res$per_day$slope_mV_dec[res$per_day$day == dd]
  }, 0)
  b_ratio = if (!is.null(bg) && !is.null(bg$per_day) && nrow(bg$per_day)) {
    b = bg$per_day$b_bkg_M[match(days, bg$per_day$day)]; b / min(b, na.rm = TRUE) } else rep(NA_real_, length(days))
  check = vapply(days, function(dd) {
    p = pts[pts$day == dd, ]; xv = p$E_mV[toupper(p$letter) == "X"]; zv = p$E_mV[toupper(p$letter) == "Z"]
    if (length(xv) && length(zv)) zv[1] - xv[1] else NA_real_ }, 0)
  unsettled = vapply(days, function(dd) {
    if (is.null(settle)) return(NA_real_)
    s = settle[settle$day == dd & settle$fit, ]; if (!nrow(s)) return(NA_real_)
    mean(is.na(s$settled_s) | s$settled_s > read_s) }, 0)
  signs = data.frame(day = days, pct_nernst = res$per_day$pct_nernst, low_end_ratio = low_ratio, background_ratio = b_ratio,
                     check_drift_mV = check, r2 = res$per_day$r2, unsettled_share = unsettled)
  f = with(signs, data.frame(day,
    slope_low = !is.na(pct_nernst) & pct_nernst < th$slope_lo, slope_high = !is.na(pct_nernst) & pct_nernst > th$slope_hi,
    low_end = !is.na(low_end_ratio) & low_end_ratio < th$low_end, background = !is.na(background_ratio) & background_ratio > th$background,
    drift = !is.na(check_drift_mV) & abs(check_drift_mV) > th$drift_mV, scatter = !is.na(r2) & r2 < th$r2,
    unsettled = !is.na(unsettled_share) & unsettled_share > th$unsettled))
  causes = do.call(rbind, lapply(seq_len(nrow(f)), function(i) {
    g = f[i, ]; out = character(0)
    # the wording names only the signs that were flagged on that day
    if (g$low_end && g$background)
      out = c(out, "Low end flattening with the background up: more Li⁺ than intended in the dilute standards, or Li⁺ released at the membrane surface. Check: fresh dilute standards in clean tubes, rinsing between standards, the membrane surface (clean or soak).")
    else if (g$low_end)
      out = c(out, "Low end flattening: the dilute standards give less response than the rest of the line. Check: fresh dilute standards in clean tubes, rinsing between standards, the membrane surface, and the detection limit expected for this membrane.")
    if (g$slope_low && !g$low_end)
      out = c(out, "Slope low over the whole range. Check the reference electrode (filling solution, junction, and against a second reference). Also check the temperature and the membrane (cracks, seal).")
    if (g$slope_high)
      out = c(out, "Slope above Nernstian: a mixed potential or a changing ionic strength. A constant background electrolyte, or the fit against concentration, tests this.")
    if (g$drift)
      out = c(out, sprintf("Check standard moved by %.1f mV within the session: carry-over from the concentrated standards, or a drifting reference. Check: rinse and re-read the check standard after the highest standards, and compare the reference with a second one.", signs$check_drift_mV[i]))
    if (g$scatter) out = c(out, "Scatter about the line: check the order and labels of the standards, and standards read before the potential settled.")
    if (g$unsettled) out = c(out, "Several standards were still drifting at the reading time: read later or record longer (Reading time tab).")
    if (!length(out)) out = "No sign flagged."
    data.frame(day = g$day, signs = paste(names(g)[-1][unlist(g[-1])], collapse = ", "), check = out)
  }))
  causes$signs[causes$signs == ""] = "none"
  list(signs = signs, flags = f, causes = causes)
}

# Electrochemical impedance: reading, checking, plotting data, equivalent circuits written as text,
# fitting, ranking, Kramers-Kronig validation and cautious interpretation.
#
# Circuits are written in a short notation: elements joined by "-" are in series and p(a, b, ...)
# holds elements in parallel, for example "Rs-p(Rct,Q)" or "Rs-p(Q,Rct-W)". Elements:
#   R  resistor (ohm)                 C  capacitor (F)
#   Q  constant phase element, Z = 1 / (Q (j w)^n); parameters Q (S s^n) and n
#   W  semi-infinite Warburg, Z = sigma w^-1/2 (1 - j); parameter sigma (ohm s^-1/2)
#   Wo finite Warburg, reflective (open): R coth(s)/s, s = (j w tau)^1/2; parameters R and tau
#   Ws finite Warburg, transmissive (short): R tanh(s)/s; parameters R and tau
#   L  inductor (H)
# An element can carry a label after its letter (Rs, Rct, Q1, Wo2, ...), which names its parameters:
# Q1 has Q1 and n1, W has sigma, W2 has sigma2, Wo1 has R_Wo1 and tau_Wo1.
# Zim is the imaginary part as measured (negative for a capacitor); plots show -Z''.

eis_kinds = c("Wo", "Ws", "R", "C", "Q", "W", "L")

# Parse the notation into a tree of series and parallel nodes
eis_parse = function(s) {
  s = gsub("[[:space:]]", "", s)
  split_top = function(x, sep) {             # split at sep where not inside brackets
    out = character(); depth = 0; start = 1
    for (i in seq_len(nchar(x))) { ch = substr(x, i, i)
      if (ch == "(") depth = depth + 1 else if (ch == ")") depth = depth - 1
      else if (ch == sep && depth == 0) { out = c(out, substr(x, start, i - 1)); start = i + 1 } }
    c(out, substr(x, start, nchar(x)))
  }
  node = function(x) {
    parts = split_top(x, "-")
    if (length(parts) > 1) return(list(type = "series", kids = lapply(parts, node)))
    if (grepl("^p\\(.*\\)$", x)) return(list(type = "parallel", kids = lapply(split_top(substr(x, 3, nchar(x) - 1), ","), node)))
    if (grepl("^\\(.*\\)$", x)) return(node(substr(x, 2, nchar(x) - 1)))
    k = eis_kinds[startsWith(x, eis_kinds)][1]
    if (is.na(k)) stop("unknown element '", x, "' (use R, C, Q, W, Wo, Ws or L, with an optional label)")
    lab = substr(x, nchar(k) + 1, nchar(x))
    if (grepl("[^A-Za-z0-9_]", lab)) stop("element '", x, "': a label may only hold letters, digits and _")
    list(type = "element", kind = k, name = x, label = lab)
  }
  node(s)
}
eis_elements = function(t) if (t$type == "element") list(t) else do.call(c, lapply(t$kids, eis_elements))
eis_param_names = function(el) switch(el$kind, R = el$name, C = el$name, L = el$name,
  Q = c(el$name, paste0("n", el$label)), W = paste0("sigma", el$label),
  Wo = c(paste0("R_", el$name), paste0("tau_", el$name)), Ws = c(paste0("R_", el$name), paste0("tau_", el$name)))

# Compile a circuit: parameter names, which are CPE exponents, the impedance function and a description
eis_compile = function(s) {
  tree = eis_parse(s); els = eis_elements(tree)
  if (anyDuplicated(vapply(els, `[[`, "", "name"))) stop("circuit '", s, "': each element needs its own label")
  pn = unlist(lapply(els, eis_param_names)); idx = list(); k = 0
  for (e in els) { m = length(eis_param_names(e)); idx[[e$name]] = k + seq_len(m); k = k + m }
  z = function(t, w, p) switch(t$type,
    series = Reduce(`+`, lapply(t$kids, z, w = w, p = p)),
    parallel = 1 / Reduce(`+`, lapply(t$kids, function(k) 1 / z(k, w, p))),
    element = { q = p[idx[[t$name]]]
      switch(t$kind, R = complex(real = q[1], imaginary = 0 * w), C = 1 / (1i * w * q[1]), L = 1i * w * q[1],
             Q = 1 / (q[1] * (1i * w)^q[2]), W = q[1] * (1 - 1i) / sqrt(w),
             Wo = { u = sqrt(1i * w * q[2]); q[1] / (tanh(u) * u) }, Ws = { u = sqrt(1i * w * q[2]); q[1] * tanh(u) / u }) })
  list(string = s, tree = tree, elements = els, p = pn, exponent = grepl("^n", pn) & pn %in% unlist(lapply(els, function(e) if (e$kind == "Q") paste0("n", e$label))),
       f = function(w, p) z(tree, w, p), notation = eis_notation(tree))
}
eis_notation = function(t) switch(t$type, element = t$name,
  series = paste(vapply(t$kids, eis_notation, ""), collapse = " + "),
  parallel = paste0("(", paste(vapply(t$kids, eis_notation, ""), collapse = " || "), ")"))   # plain || so every font and PDF can show it

# Candidate circuits tried by default (the first four are the ones listed in the EIS requirements)
eis_library = c("Rs-p(Rct,C)", "Rs-p(Rct,Q)", "Rs-p(C,Rct-W)", "Rs-Q", "Rs-C", "Rs-p(Q,Rct-W)", "Rs-p(Q,Rct-Wo)",
                "Rs-p(Q,Rct-Ws)", "Rs-p(R1,Q1)-p(R2,Q2)", "Rs-p(Q1,R1-p(R2,Q2))", "Rs-p(Rct,Q)-W")

# Starting values from the shape of the spectrum: series R from the high-frequency real part, other
# resistances from the arc width, capacitances from the frequency at the top of the arc, sigma from the
# low-frequency end, tau from the lowest frequency
eis_start = function(d, cc) {
  w = 2 * pi * d$freq_Hz; Zr = Re(d$Z); Zi = Im(d$Z)
  Rs = max(min(Zr), 1e-6); Rp = max(max(Zr) - Rs, Rs); Cg = 1 / (w[which.max(-Zi)] * Rp)
  sg = max(abs(Zi[which.min(w)]) * sqrt(min(w)), 1e-6)
  top = if (cc$tree$type == "series") vapply(cc$tree$kids, function(k) if (k$type == "element") k$name else "", "") else ""
  nR = sum(vapply(cc$elements, function(e) e$kind == "R" && !e$name %in% top[1], TRUE))
  v = unlist(lapply(cc$elements, function(e) switch(e$kind,
    R = if (e$name %in% top) Rs else Rp / max(nR, 1), C = Cg, L = 1e-7, Q = c(Cg, 0.9), W = sg, Wo = c(Rp, 1 / min(w)), Ws = c(Rp, 1 / min(w)))))
  stats::setNames(v, cc$p)
}
# "R1=1000, n=0.9" or "R1=1e3:1e8" into a named vector or a two-column matrix
eis_named = function(txt) { if (is.null(txt) || !nzchar(trimws(txt))) return(NULL)
  kv = strsplit(trimws(strsplit(txt, "[,;]")[[1]]), "=")
  stats::setNames(vapply(kv, function(x) trimws(x[2]), ""), vapply(kv, function(x) trimws(x[1]), "")) }

# Weighted complex nonlinear least squares. Weighting: "modulus" (1/|Z| on both parts, the default),
# "proportional" (1/|Z'| and 1/|Z''| separately) or "unit" (none). Parameters are fitted on a log scale
# (CPE exponents on a logistic scale between 0 and 1), from several starts. Optional starting values and
# bounds as text, for example start = "Rct=2e6" and bounds = "Rct=1e5:1e8, n=0.5:1".
eis_fit = function(d, circuit, weighting = c("modulus", "proportional", "unit"), start = NULL, bounds = NULL, starts = 12, seed = 1) {
  weighting = match.arg(weighting); cc = eis_compile(circuit); pn = cc$p; ex = cc$exponent
  w = 2 * pi * d$freq_Hz; Zm = d$Z
  wr = switch(weighting, modulus = 1 / Mod(Zm), proportional = 1 / pmax(abs(Re(Zm)), 1e-12), unit = rep(1, length(w)))
  wi = switch(weighting, modulus = 1 / Mod(Zm), proportional = 1 / pmax(abs(Im(Zm)), 1e-12), unit = rep(1, length(w)))
  lo = ifelse(ex, 0, 0); hi = ifelse(ex, 1, Inf)
  b = eis_named(bounds)
  for (k in intersect(names(b), pn)) { r = as.numeric(strsplit(b[[k]], ":")[[1]]); lo[pn == k] = r[1]; hi[pn == k] = r[2] }
  to_p = function(u) ifelse(ex, lo + (pmin(hi, 1) - lo) / (1 + exp(-u)), exp(u))
  to_u = function(p) ifelse(ex, -log((pmin(hi, 1) - lo) / pmin(pmax(p - lo, 1e-6), pmin(hi, 1) - lo - 1e-6) - 1), log(p))
  ssr = function(u) { p = to_p(u)
    if (any(!ex & (p < lo | p > hi))) return(1e30)
    z = cc$f(w, p); s = sum(((Re(z) - Re(Zm)) * wr)^2 + ((Im(z) - Im(Zm)) * wi)^2); if (is.finite(s)) s else 1e30 }
  p0 = eis_start(d, cc); s0 = eis_named(start)
  for (k in intersect(names(s0), pn)) p0[[k]] = as.numeric(s0[[k]])
  p0 = ifelse(!ex & is.finite(hi), pmin(pmax(p0, lo), hi), pmax(p0, ifelse(ex, 0, lo)))
  set.seed(seed); best = NULL
  for (k in seq_len(starts)) {
    u0 = to_u(p0) + if (k == 1) 0 else stats::rnorm(length(pn), 0, ifelse(ex, 0.5, 1.5))
    o = tryCatch(stats::optim(u0, ssr, method = "Nelder-Mead", control = list(maxit = 4000, reltol = 1e-12)), error = function(e) NULL)
    if (!is.null(o)) o = tryCatch(stats::optim(o$par, ssr, method = "BFGS", control = list(maxit = 2000, reltol = 1e-14)), error = function(e) o)
    if (!is.null(o) && (is.null(best) || o$value < best$value)) best = o
  }
  N = 2 * length(w); np = length(pn); p = to_p(best$par); s2 = best$value / max(N - np, 1)
  # standard errors from the Hessian of the weighted sum of squares, on the fitting scale, carried to the
  # parameter scale by the delta method
  H = tryCatch(stats::optimHess(best$par, ssr), error = function(e) NULL)
  se_u = if (!is.null(H)) tryCatch(sqrt(pmax(diag(solve(H / 2)) * s2, 0)), error = function(e) rep(NA, np)) else rep(NA, np)
  dpdu = ifelse(ex, (p - lo) * (1 - (p - lo) / (pmin(hi, 1) - lo)), p)
  se = abs(dpdu) * se_u
  fz = cc$f(w, p); res = fz - Zm
  at_bound = (ex & (p > pmin(hi, 1) - 0.005 | p < lo + 0.005)) | (!ex & ((is.finite(hi) & p > 0.99 * hi) | (lo > 0 & p < 1.01 * lo)))
  list(circuit = circuit, notation = cc$notation, weighting = weighting,
       params = data.frame(parameter = pn, value = p, se = se, rel_se_pct = 100 * se / abs(p), at_bound = at_bound,
                           unit = eis_param_unit(pn, cc)),
       start_values = p0, chi2 = best$value, chi2_red = s2, n_points = N, n_params = np,
       rmse_ohm = sqrt(mean(c(Re(res), Im(res))^2)), nrmse_pct = 100 * sqrt(mean(c(Re(res), Im(res))^2 / Mod(Zm)^2)),
       aic = N * log(best$value / N) + 2 * np, aicc = N * log(best$value / N) + 2 * np + 2 * np * (np + 1) / max(N - np - 1, 1),
       bic = N * log(best$value / N) + np * log(N), converged = best$convergence == 0, fit_Z = fz,
       residuals = data.frame(freq_Hz = d$freq_Hz, res_re_pct = 100 * Re(res) / Mod(Zm), res_im_pct = 100 * Im(res) / Mod(Zm)))
}
eis_param_unit = function(pn, cc) vapply(pn, function(k) {
  e = cc$elements[[which(vapply(cc$elements, function(e) k %in% eis_param_names(e), TRUE))[1]]]
  switch(e$kind, R = "ohm", C = "F", L = "H", W = "ohm s^-1/2", Q = if (startsWith(k, "n")) "" else "S s^n",
         Wo = , Ws = if (startsWith(k, "tau")) "s" else "ohm")
}, "")

# Linear Kramers-Kronig test (Schonleber et al., Electrochim. Acta 2014, 131, 20): a series resistance,
# M RC elements with time constants spread evenly on a log scale over the measured range, a series
# capacitance and an inductance, all linear in the unknowns. M grows until mu = 1 - sum|R_k<0| / sum|R_k>=0|
# falls below 0.85. Small, structureless residuals mean the data behave as a linear, causal, stable system.
lin_kk = function(d, c_mu = 0.85, M_max = 60) {
  w = 2 * pi * d$freq_Hz; Z = d$Z; wt = 1 / Mod(Z)
  solve_M = function(M) {
    tau = 10^seq(log10(1 / max(w)), log10(1 / min(w)), length.out = M)
    Xr = cbind(1, sapply(tau, function(t) 1 / (1 + (w * t)^2)), 0, 0)
    Xi = cbind(0, sapply(tau, function(t) -w * t / (1 + (w * t)^2)), -1 / w, w)
    b = qr.solve(rbind(Xr * wt, Xi * wt), c(Re(Z) * wt, Im(Z) * wt))
    Rk = b[2:(M + 1)]
    list(M = M, mu = 1 - sum(abs(Rk[Rk < 0])) / sum(abs(Rk[Rk >= 0])), fit = complex(real = drop(Xr %*% b), imaginary = drop(Xi %*% b)))
  }
  for (M in seq_len(M_max)) { s = solve_M(M); if (M > 1 && s$mu <= c_mu) break }
  rr = (Re(Z) - Re(s$fit)) / Mod(Z); ri = (Im(Z) - Im(s$fit)) / Mod(Z)
  list(M = s$M, mu = s$mu, residuals = data.frame(freq_Hz = d$freq_Hz, res_re_pct = 100 * rr, res_im_pct = 100 * ri),
       max_abs_res_pct = 100 * max(abs(c(rr, ri))), rms_res_pct = 100 * sqrt(mean(c(rr, ri)^2)))
}

# Checks on the data as read: missing or repeated frequencies, sign convention, and agreement of
# |Z| and phase recomputed from Z' and Z'' with the columns in the file when it has them
eis_validate = function(e) {
  d = e$data; out = list()
  out$points = nrow(d); out$freq_range = sprintf("%g to %g Hz", min(d$freq_Hz), max(d$freq_Hz))
  out$repeated_frequencies = sum(duplicated(d$freq_Hz))
  out$missing_or_nonfinite = if (!is.null(e$dropped)) e$dropped else 0
  out$share_capacitive = mean(Im(d$Z) < 0)
  if (!is.null(e$file_mod)) out$max_mod_diff_pct = 100 * max(abs(Mod(d$Z) - e$file_mod) / e$file_mod)
  if (!is.null(e$file_phase)) out$max_phase_diff_deg = max(abs(abs(Arg(d$Z) * 180 / pi) - abs(e$file_phase)))
  flags = character()
  if (out$repeated_frequencies) flags = c(flags, sprintf("%d repeated frequencies", out$repeated_frequencies))
  if (out$missing_or_nonfinite) flags = c(flags, sprintf("%d rows without usable numbers were left out", out$missing_or_nonfinite))
  if (out$share_capacitive < 0.5) flags = c(flags, "most points have Z'' > 0: check the sign convention of the imaginary column")
  if (!is.null(out$max_mod_diff_pct) && out$max_mod_diff_pct > 1) flags = c(flags, "|Z| in the file does not match Z' and Z''")
  if (!is.null(out$max_phase_diff_deg) && out$max_phase_diff_deg > 1) flags = c(flags, "the phase in the file does not match Z' and Z''")
  out$flags = if (length(flags)) paste(flags, collapse = "; ") else "none"
  out$note = e$note
  out
}

# Features of the spectrum that point to circuit families, read before any fit
eis_features = function(d) {
  f = d$freq_Hz; Z = d$Z; ph = Arg(Z) * 180 / pi; o = order(f); f = f[o]; Z = Z[o]; ph = ph[o]
  low = f <= 10 * min(f); high = f >= max(f) / 10
  slope_low = unname(stats::coef(stats::lm(log10(Mod(Z[low])) ~ log10(f[low])))[2])
  mz = -Im(Z); peaks = which(diff(sign(diff(stats::filter(mz, rep(1 / 3, 3), sides = 2)))) == -2) + 1
  out = data.frame(high_f_real_ohm = Re(Z[which.max(f)]), low_f_phase_deg = ph[1], low_f_logZ_slope = slope_low,
                   min_phase_deg = min(ph), f_at_min_phase_Hz = f[which.min(ph)], local_maxima_of_minus_Zim = length(peaks))
  hints = c(sprintf("Series resistance about %.3g ohm (real part at the highest frequency).", out$high_f_real_ohm))
  hints = c(hints, if (slope_low < -0.85 && ph[1] < -75) "Low-frequency |Z| slope near -1 and phase near -90 degrees: a blocking (capacitive) interface. Try Rs-C or Rs-Q. An Rct too large to resolve looks the same."
    else if (slope_low > -0.65 && slope_low < -0.35 && ph[1] < -30 && ph[1] > -60) "Low-frequency |Z| slope near -0.5 and phase near -45 degrees: diffusion (Warburg) or a strongly non-ideal interface (CPE n near 0.5)."
    else if (slope_low > -0.2) "Low-frequency |Z| levels off: a finite resistance in parallel with the interface (charge transfer or a transmissive finite diffusion)."
    else "Low-frequency behaviour between the ideal cases: compare circuits with a CPE and with diffusion elements.")
  if (out$local_maxima_of_minus_Zim >= 2) hints = c(hints, "-Z'' has more than one maximum: more than one time constant (two RC/RQ elements or nested circuits).")
  list(features = out, hints = hints)
}

# Effective capacitance of a CPE, only where a resistance is in parallel with it:
# Hsu and Mansfeld, C = (Q R^(1-n))^(1/n) with R the parallel resistance (the form in the EIS
# requirements; Zahner documentation eq. 7), and Brug et al. (J. Electroanal. Chem. 1984, 176, 275),
# C = Q^(1/n) (Rs Rp / (Rs + Rp))^((1-n)/n) (Zahner eq. 8)
hsu_mansfeld_capacitance = function(Q, n, R) (Q * R^(1 - n))^(1 / n)
brug_capacitance = function(Q, n, Rs, Rp) Q^(1 / n) * (Rs * Rp / (Rs + Rp))^((1 - n) / n)
# k0 = R T / (n^2 F^2 A Rct C), equal concentrations of both forms of the probe, small amplitude at the
# formal potential (Microchim. Acta 2023, 190, 251, eq. 17)
k0_from_rct = function(Rct_ohm, area_cm2, C_mM, n = 1, T_K = 298.15) R_const * T_K / (n^2 * F_const^2 * area_cm2 * Rct_ohm * mM_to_mol_cm3(C_mM))
# D from the Warburg coefficient with equal D and C of both forms:
# sigma = R T / (n^2 F^2 A 2^1/2) (1/(C_O D_O^1/2) + 1/(C_R D_R^1/2)) (Bard and Faulkner)
D_from_warburg = function(sigma, area_cm2, C_mM, n = 1, T_K = 298.15)
  (2 * R_const * T_K / (n^2 * F_const^2 * area_cm2 * sqrt(2) * mM_to_mol_cm3(C_mM) * sigma))^2

# Quantities that follow from a fit, each computed only when its circuit supports it
eis_derived = function(fit, area_cm2 = NA, C_mM = NA, n_e = 1, T_K = 298.15) {
  cc = eis_compile(fit$circuit); p = stats::setNames(fit$params$value, fit$params$parameter); out = list()
  series_R = if (cc$tree$type == "series") Filter(function(k) k$type == "element" && k$kind == "R", cc$tree$kids) else list()
  Rs = if (length(series_R)) p[[series_R[[1]]$name]] else NA
  # every parallel pair of one R and one Q gives an effective capacitance
  walk = function(t) if (t$type == "element") list() else c(
    if (t$type == "parallel" && length(t$kids) == 2 && all(vapply(t$kids, function(k) k$type == "element", TRUE))) {
      kinds = vapply(t$kids, `[[`, "", "kind")
      if (setequal(kinds, c("R", "Q"))) list(list(R = t$kids[[which(kinds == "R")]], Q = t$kids[[which(kinds == "Q")]])) }, do.call(c, lapply(t$kids, walk)))
  for (pr in walk(cc$tree)) {
    Q = p[[pr$Q$name]]; nn = p[[paste0("n", pr$Q$label)]]; R = p[[pr$R$name]]
    out[[paste0("C_eff_HsuMansfeld_", pr$Q$name, "_F")]] = hsu_mansfeld_capacitance(Q, nn, R)
    if (!is.na(Rs)) out[[paste0("C_eff_Brug_", pr$Q$name, "_F")]] = brug_capacitance(Q, nn, Rs, R)
  }
  for (k in names(p)) if (grepl("^Rct", k) || (k %in% c("R1", "R2") && !k %in% if (!is.na(Rs)) series_R[[1]]$name)) {
    if (!is.na(area_cm2)) out[[paste0(k, "_area_ohm_cm2")]] = p[[k]] * area_cm2
    if (grepl("^Rct", k) && !is.na(area_cm2) && !is.na(C_mM)) out[[paste0("k0_from_", k, "_cm_s")]] = k0_from_rct(p[[k]], area_cm2, C_mM, n_e, T_K)
  }
  for (k in grep("^sigma", names(p), value = TRUE)) if (!is.na(area_cm2) && !is.na(C_mM)) out[[paste0("D_from_", k, "_cm2_s")]] = D_from_warburg(p[[k]], area_cm2, C_mM, n_e, T_K)
  out
}

# A cautious reading of one fit: what is supported by the numbers and what is not
eis_interpret = function(fit, kk = NULL, feats = NULL) {
  p = fit$params; v = stats::setNames(p$value, p$parameter); s = stats::setNames(p$rel_se_pct, p$parameter); txt = character()
  if (!is.null(kk)) txt = c(txt, sprintf("Kramers-Kronig check: largest residual %.1f%% of |Z|, RMS %.2f%%. %s", kk$max_abs_res_pct, kk$rms_res_pct,
    if (kk$max_abs_res_pct < 2) "The data are consistent with a linear, stable system." else if (kk$max_abs_res_pct < 5) "Small departures. Look at where the residuals sit in frequency." else "Large departures: drift or nonlinearity is likely, and fitted values should not be trusted."))
  if ("Rs" %in% names(v)) txt = c(txt, sprintf("Series (electrolyte and contact) resistance Rs = %.3g ohm (error %.1f%%).", v[["Rs"]], s[["Rs"]]))
  for (k in grep("^n", names(v), value = TRUE)) txt = c(txt, sprintf("CPE exponent %s = %.2f: %s", k, v[[k]],
    if (v[[k]] > 0.9) "close to an ideal capacitor." else if (v[[k]] > 0.7) "a non-ideal capacitive interface (roughness, inhomogeneity)." else if (v[[k]] > 0.4) "far from a capacitor, as for diffusion or a distributed process." else "resistive behaviour. The element may not be a capacitance at all."))
  for (k in grep("^R(ct|[0-9])", names(v), value = TRUE)) txt = c(txt, if (is.finite(s[[k]]) && s[[k]] < 30) sprintf("%s = %.3g ohm is determined by the data (error %.0f%%).", k, v[[k]], s[[k]])
    else sprintf("%s = %.3g ohm is not well determined (error %s): do not report it as a charge-transfer resistance.", k, v[[k]], if (is.finite(s[[k]])) sprintf("%.0f%%", s[[k]]) else "not estimable"))
  for (k in grep("^sigma", names(v), value = TRUE)) txt = c(txt, sprintf("Warburg coefficient %s = %.3g ohm s^-1/2 (error %.0f%%): %s", k, v[[k]], s[[k]],
    if (s[[k]] < 30) "a diffusion contribution is supported by this fit." else "the diffusion term is weakly determined."))
  for (k in grep("^R_W[os]", names(v), value = TRUE)) { tk = sub("^R_", "tau_", k)
    txt = c(txt, sprintf("Finite-length diffusion %s: R = %.3g ohm (error %.0f%%), tau = %.3g s (error %.0f%%). %s", sub("^R_", "", k), v[[k]], s[[k]], v[[tk]], s[[tk]],
      if (startsWith(sub("^R_", "", k), "Wo")) "A reflective (open) boundary: the low-frequency branch turns capacitive, as for a layer the species cannot leave."
      else "A transmissive (short) boundary: the low-frequency branch turns resistive, as for diffusion through a layer of finite thickness.")) }
  if (any(p$at_bound)) txt = c(txt, sprintf("At a bound: %s. The optimum lies outside the allowed range or the parameter is not identifiable.", paste(p$parameter[p$at_bound], collapse = ", ")))
  if (!fit$converged) txt = c(txt, "The optimizer did not report convergence: treat the values with caution.")
  txt = c(txt, "A better fit statistic does not prove a circuit is the physically correct one. Keep the circuit whose elements make sense for the system.")
  txt
}

# Layout of a circuit diagram: boxes for elements, lines for wires (drawn by the app with ggplot2)
eis_diagram = function(circuit) {
  tree = eis_parse(circuit)
  size = function(t) switch(t$type, element = c(1.4, 1),
    series = { s = sapply(t$kids, size); c(sum(s[1, ]) + 0.4 * (ncol(s) - 1), max(s[2, ])) },
    parallel = { s = sapply(t$kids, size); c(max(s[1, ]) + 0.8, sum(s[2, ]) + 0.3 * (ncol(s) - 1)) })
  boxes = list(); wires = list()
  draw = function(t, x0, yc) { sz = size(t)
    if (t$type == "element") { boxes[[length(boxes) + 1]] <<- data.frame(xmin = x0 + 0.1, xmax = x0 + sz[1] - 0.1, ymin = yc - 0.3, ymax = yc + 0.3, label = t$name)
      wires[[length(wires) + 1]] <<- data.frame(x = c(x0, x0 + sz[1] - 0.1), xend = c(x0 + 0.1, x0 + sz[1]), y = yc, yend = yc); return(invisible()) }
    if (t$type == "series") { x = x0
      for (i in seq_along(t$kids)) { k = t$kids[[i]]; s = size(k); draw(k, x, yc)
        if (i < length(t$kids)) wires[[length(wires) + 1]] <<- data.frame(x = x + s[1], xend = x + s[1] + 0.4, y = yc, yend = yc)
        x = x + s[1] + 0.4 }
      return(invisible()) }
    s = sapply(t$kids, size); tot = sum(s[2, ]) + 0.3 * (ncol(s) - 1); y = yc + tot / 2; ys = numeric()
    for (i in seq_along(t$kids)) { yk = y - s[2, i] / 2; ys = c(ys, yk)
      draw(t$kids[[i]], x0 + 0.4 + (sz[1] - 0.8 - s[1, i]) / 2, yk)
      wires[[length(wires) + 1]] <<- data.frame(x = c(x0 + 0.4, x0 + 0.4 + (sz[1] - 0.8 + s[1, i]) / 2), xend = c(x0 + 0.4 + (sz[1] - 0.8 - s[1, i]) / 2, x0 + sz[1] - 0.4), y = yk, yend = yk)
      y = y - s[2, i] - 0.3 }
    wires[[length(wires) + 1]] <<- data.frame(x = c(x0, x0 + 0.4, x0 + sz[1] - 0.4, x0 + sz[1] - 0.4), xend = c(x0 + 0.4, x0 + 0.4, x0 + sz[1] - 0.4, x0 + sz[1]),
                                              y = c(yc, max(ys), max(ys), yc), yend = c(yc, min(ys), min(ys), yc))
  }
  sz = size(tree); draw(tree, 0.6, 0)
  wires[[length(wires) + 1]] = data.frame(x = c(0, sz[1] + 0.6), xend = c(0.6, sz[1] + 1.2), y = 0, yend = 0)
  list(boxes = do.call(rbind, boxes), wires = do.call(rbind, wires), width = sz[1] + 1.2, height = sz[2])
}

# Display units: values are divided only for plots and tables; fitting always uses ohm, Hz and F
unit_factor = function(u) c(ohm = 1, kohm = 1e3, Mohm = 1e6, Gohm = 1e9, Hz = 1, kHz = 1e3, MHz = 1e6,
                            F = 1, mF = 1e-3, uF = 1e-6, nF = 1e-9, pF = 1e-12)[[u]]
unit_label = function(u) c(ohm = "Ω", kohm = "kΩ", Mohm = "MΩ", Gohm = "GΩ", Hz = "Hz", kHz = "kHz", MHz = "MHz",
                           F = "F", mF = "mF", uF = "µF", nF = "nF", pF = "pF")[[u]]
auto_ohm = function(z) { m = max(abs(c(Re(z), Im(z)))); if (m >= 1e9) "Gohm" else if (m >= 1e6) "Mohm" else if (m >= 1e3) "kohm" else "ohm" }

# Impedance files: a PalmSens session, or any text or CSV export with a frequency column and the real and
# imaginary parts (CHI "Freq/Hz, Z'/ohm, Z"/ohm, Z/ohm, Phase/deg", or names such as Zre, Re(Z), Zim,
# -Im(Z), -Z''). A leading minus in the name means the column holds -Z''. When no column says so and most
# values are positive, the column is taken as -Z'' and a note is returned. |Z| and phase columns, when
# present, are kept for the validation check.
read_eis = function(path, name = basename(path), instrument = "auto") {
  fmt = instrument_format(path, name, instrument)
  if (fmt == "pssession") {
    r = read_pssession(path, name)
    if (r$kind != "eis") stop(name, " is not an impedance measurement")
    return(list(file = name, data = r$data, note = "", dropped = 0))
  }
  if (fmt %in% c("biologic", "gamry", "mpr")) {
    r = switch(fmt, biologic = read_biologic_mpt(path, name), gamry = read_gamry_dta(path, name), mpr = read_biologic_mpr(path, name))
    if (r$kind != "eis") stop(name, " is not an impedance measurement (", r$params$technique, ")")
    d = r$data[order(-r$data$freq_Hz), ]
    return(list(file = name, data = d, note = "", dropped = 0))
  }
  L = readLines(path, warn = FALSE, encoding = "UTF-8")
  # CHI "data only" export: frequency, Z', Z'', |Z|, phase with no header
  if (fmt == "chi" && !any(grepl("freq", L[1:min(60, length(L))], ignore.case = TRUE))) {
    r = read_chi_txt(path, name)
    if (!identical(r$kind, "eis")) stop(name, " is not an impedance measurement (", r$params$technique, ")")
    d = r$data[is.finite(r$data$freq_Hz) & r$data$freq_Hz > 0, ]
    return(list(file = name, data = d[order(-d$freq_Hz), ], note = "", dropped = 0))
  }
  hdr = which(grepl("freq", L, ignore.case = TRUE) & grepl("[,;\t]", L))
  if (!length(hdr)) stop(name, ": no header line with a frequency column was found")
  h = hdr[length(hdr)]
  sep = if (grepl("\t", L[h])) "\t" else if (grepl(";", L[h])) ";" else ","
  tab = utils::read.table(text = L[h:length(L)], sep = sep, header = TRUE, check.names = FALSE, fill = TRUE,
                          strip.white = TRUE, comment.char = "", quote = "", stringsAsFactors = FALSE)
  # names written by CSV writers come in quotes; strip them so a quote is not read as Z"
  nm = gsub('^"|"$', "", trimws(names(tab))); low = tolower(gsub("[[:space:]]", "", nm))
  fcol = which(grepl("freq", low))[1]
  icol = which(grepl("z''|z\"|zim|im\\(z\\)|zimag|imag", low))[1]
  rcol = which(grepl("z'|zre|re\\(z\\)|zreal|real", low) & !seq_along(low) %in% icol)[1]
  mcol = which(grepl("^\\|?z\\|?(/|$|\\()|^mod|^\\|z\\|", low) & !seq_along(low) %in% c(rcol, icol))[1]
  pcol = which(grepl("phase", low))[1]
  if (any(is.na(c(fcol, rcol, icol)))) stop(name, ": columns for frequency, Z' and Z'' were not all found (columns: ", paste(nm, collapse = ", "), ")")
  num = function(v) suppressWarnings(as.numeric(v))
  f = num(tab[[fcol]]); zr = num(tab[[rcol]]); zi = num(tab[[icol]])
  zm = if (!is.na(mcol)) num(tab[[mcol]]) else NULL; ph = if (!is.na(pcol)) num(tab[[pcol]]) else NULL
  k = is.finite(f) & is.finite(zr) & is.finite(zi) & f > 0
  dropped = sum(!k & rowSums(!is.na(tab)) > 0)
  f = f[k]; zr = zr[k]; zi = zi[k]; zm = zm[k]; ph = ph[k]
  note = ""
  if (grepl("^-", low[icol])) zi = -zi
  else if (mean(zi > 0) > 0.5) { zi = -zi; note = "imaginary column read as -Z'' (most values were positive)" }
  o = order(-f)
  list(file = name, data = data.frame(freq_Hz = f[o], Z = complex(real = zr[o], imaginary = zi[o])), note = note, dropped = dropped,
       file_mod = if (length(zm)) zm[o] else NULL, file_phase = if (length(ph)) ph[o] else NULL)
}

# Quality control across sessions: a history of results (one row per session and quantity), control limits from a
# reference period, and the Westgard multi-rule checks (Westgard, Barry, Hunt and Groth, Clin. Chem. 1981, 27, 493):
#   1-3s  one point beyond 3 SD                      2-2s  two in a row beyond 2 SD on the same side
#   R-4s  two in a row more than 4 SD apart (applied here to consecutive sessions)   4-1s  four in a row beyond 1 SD on the same side
#   10x   ten in a row on the same side of the mean
# 1-2s (one point beyond 2 SD) is a warning only. shinyapps.io keeps nothing between visits, so the history lives
# in a CSV the user downloads and loads again next time.

qc_columns = c("date", "quantity", "value", "unit", "electrode", "note")
qc_template = function() data.frame(date = character(), quantity = character(), value = numeric(), unit = character(),
                                     electrode = character(), note = character())

qc_read = function(path) {
  h = utils::read.csv(path, stringsAsFactors = FALSE, check.names = FALSE)
  names(h) = tolower(trimws(names(h)))
  miss = setdiff(c("date", "quantity", "value"), names(h))
  if (length(miss)) stop("The history needs the columns date, quantity and value (missing: ", paste(miss, collapse = ", "), ")")
  for (k in setdiff(qc_columns, names(h))) h[[k]] = ""
  h$value = suppressWarnings(as.numeric(h$value))
  h[, qc_columns]
}

# Limits from the first n_ref points of each quantity (all points when n_ref is NA)
qc_limits = function(h, n_ref = NA) do.call(rbind, lapply(split(h, h$quantity), function(d) {
  d = d[order(d$date), ]; r = if (is.na(n_ref)) d$value else utils::head(d$value, n_ref)
  data.frame(quantity = d$quantity[1], unit = d$unit[1], n_ref = length(r), mean = mean(r), sd = if (length(r) > 1) stats::sd(r) else NA)
}))

qc_rules = function(z) {
  n = length(z); f = vector("list", n)
  run = function(i, k, cond) i >= k && all(cond(z[(i - k + 1):i]))
  for (i in seq_len(n)) {
    r = character(0)
    if (abs(z[i]) > 3) r = c(r, "1-3s")
    if (run(i, 2, function(x) x > 2) || run(i, 2, function(x) x < -2)) r = c(r, "2-2s")
    if (i >= 2 && abs(z[i] - z[i - 1]) > 4) r = c(r, "R-4s")
    if (run(i, 4, function(x) x > 1) || run(i, 4, function(x) x < -1)) r = c(r, "4-1s")
    if (run(i, 10, function(x) x > 0) || run(i, 10, function(x) x < 0)) r = c(r, "10x")
    if (!length(r) && abs(z[i]) > 2) r = "1-2s (warning)"
    f[[i]] = if (length(r)) paste(r, collapse = ", ") else ""
  }
  unlist(f)
}

# Things to check when a rule fires, by the kind of quantity. These are prompts, not diagnoses.
qc_hint = function(quantity, rule) {
  if (!nzchar(rule)) return("")
  q = tolower(quantity)
  base = if (grepl("slope", q)) "standards (age, dilution, contamination), electrode surface or membrane, reference electrode, temperature"
    else if (grepl("background|b_bkg|intercept|e0", q)) "standards and blank (contamination), reference electrode drift, filling solution"
    else if (grepl("check|standard", q)) "the check standard itself, reference electrode, reading time"
    else if (grepl("ecsa|area|charge", q)) "electrode cleaning or polishing, film deposition, electrolyte, scan window"
    else "the electrode, the solutions and the instrument settings"
  # a point beyond 3 SD (or two beyond 2 SD) is read as a sudden change even when the jump also breaks R-4s
  kind = if (grepl("1-3s|2-2s|warning", rule)) "A sudden change: " else if (grepl("R-4s", rule)) "Poor repeatability: " else "A gradual shift: "
  paste0(kind, "check ", base, ".")
}

qc_table = function(h, n_ref = NA) {
  L = qc_limits(h, n_ref)
  do.call(rbind, lapply(split(h, h$quantity), function(d) {
    d = d[order(d$date), ]; l = L[L$quantity == d$quantity[1], ]
    z = if (is.finite(l$sd) && l$sd > 0) (d$value - l$mean) / l$sd else rep(0, nrow(d))
    d$z = z; d$rule = qc_rules(z); d$check = vapply(seq_len(nrow(d)), function(i) qc_hint(d$quantity[i], d$rule[i]), ""); d
  }))
}

qc_plot = function(h, n_ref = NA) {
  t = qc_table(h, n_ref); L = qc_limits(h, n_ref)
  lines = do.call(rbind, lapply(seq_len(nrow(L)), function(i) data.frame(quantity = L$quantity[i],
    y = L$mean[i] + c(-3, -2, 0, 2, 3) * ifelse(is.finite(L$sd[i]), L$sd[i], 0), kind = c("3 SD", "2 SD", "mean", "2 SD", "3 SD"))))
  t$flag = ifelse(grepl("1-3s|2-2s|R-4s|4-1s|10x", t$rule), "rule broken", ifelse(nzchar(t$rule), "warning", "in control"))
  t$date = as.Date(t$date)
  ggplot2::ggplot(t, ggplot2::aes(date, value)) +
    ggplot2::geom_hline(data = lines, ggplot2::aes(yintercept = y, linetype = kind), colour = "grey45") +
    ggplot2::geom_line(colour = "grey60") + ggplot2::geom_point(ggplot2::aes(colour = flag), size = 2.6) +
    ggplot2::scale_colour_manual(values = c(`in control` = "#1A6FDF", warning = "#E0A100", `rule broken` = "#C0392B"), drop = FALSE) +
    ggplot2::scale_linetype_manual(values = c(mean = "solid", `2 SD` = "dashed", `3 SD` = "dotted")) +
    ggplot2::facet_wrap(~ quantity, scales = "free_y", ncol = 1) + ggplot2::labs(x = NULL, y = NULL, colour = NULL, linetype = NULL)
}

# BioLogic EC-Lab binary files (.mpr) are not read in this version. A .mpr file is recognised from its first bytes, so
# that the user gets a clear message instead of a failed read: export the run from EC-Lab as text (.mpt), which the
# BioLogic reader in R/read_other.R reads.

is_mpr = function(path) { b = readBin(path, "raw", 22); identical(rawToChar(b[b != as.raw(0)]), "BIO-LOGIC MODULAR FILE") }

read_biologic_mpr = function(path, name = basename(path)) {
  stop(name, " is a BioLogic EC-Lab binary file (.mpr), which ElectroFast does not read. In EC-Lab, export the run as ",
       "text (.mpt) and load that file instead.", call. = FALSE)
}

if (!exists("%||%")) `%||%` = function(a, b) if (is.null(a)) b else a
# Readers for BioLogic EC-Lab text exports (.mpt), Gamry Framework files (.DTA) and any other delimited text
# export (for example Metrohm Autolab NOVA ASCII), returned in the same form as read_chi_txt(): data with
# E_V, I_A, t_s, Q_C, scan and segment; params with the technique, the scan rate (V/s) and the header settings.
# Units are read from each column name (A, mA, uA, nA; V, mV; s, min, h; C, mC, mA.h), never assumed.
# Layouts checked on the public example files of yadg (BioLogic, GPL-3) and gamry-parser (Gamry, MIT), October 2026.

unit_scale = function(u) {
  u = gsub("\u00b5|\u03bc", "u", trimws(u)); u = sub("^\\((.*)\\)$", "\\1", u)
  s = c(A = 1, mA = 1e-3, uA = 1e-6, nA = 1e-9, pA = 1e-12, V = 1, mV = 1e-3, uV = 1e-6, s = 1, ms = 1e-3, min = 60, h = 3600,
        C = 1, mC = 1e-3, uC = 1e-6, nC = 1e-9, "mA.h" = 3.6, "A.h" = 3600, "uA.h" = 3.6e-3, Hz = 1, kHz = 1e3, MHz = 1e6,
        Ohm = 1, ohm = 1, kOhm = 1e3, kohm = 1e3, MOhm = 1e6, Mohm = 1e6, "V vs. Ref." = 1, "V vs. Ref" = 1)
  if (u %in% names(s)) s[[u]] else NA_real_
}
# name and unit of a column: "Ewe/V", "<I>/mA", "Time (s)", "WE(1).Current (A)"
split_col = function(nm) {
  if (grepl("/", nm) && !grepl("\\(.*/.*\\)", nm)) return(c(name = sub("/[^/]*$", "", nm), unit = sub("^.*/", "", nm)))
  m = regmatches(nm, regexec("^(.*?)\\s*\\(([^()]*)\\)\\s*$", nm))[[1]]
  if (length(m) == 3) c(name = m[2], unit = m[3]) else c(name = nm, unit = "")
}
num_col = function(v, comma = FALSE) { v = trimws(as.character(v)); if (comma) v = sub(",", ".", v, fixed = TRUE); suppressWarnings(as.numeric(v)) }
add_segments = function(d) {
  if (all(is.na(d$E_V))) { d$segment = 1L; return(d) }
  dir = sign(diff(d$E_V)); dir[dir == 0] = NA; dir = c(dir[1], dir)
  for (i in seq_along(dir)[-1]) if (is.na(dir[i])) dir[i] = dir[i - 1]
  if (all(is.na(dir))) dir[] = 1
  d$segment = cumsum(c(1, diff(dir) != 0)); d
}
# pick the first column whose name matches a pattern, and convert it to SI with its own unit
pick = function(tab, nms, patterns, comma = FALSE, unit_default = NA) {
  for (p in patterns) { k = which(grepl(p, nms, ignore.case = TRUE, perl = TRUE)); if (length(k)) {
    nu = split_col(nms[k[1]]); f = unit_scale(nu[["unit"]]); if (is.na(f)) f = unit_default
    if (is.na(f)) stop("column '", nms[k[1]], "': unknown unit '", nu[["unit"]], "'")
    return(list(v = num_col(tab[[k[1]]], comma) * f, name = nms[k[1]])) } }
  NULL
}

# BioLogic EC-Lab text export (.mpt): "EC-Lab ASCII FILE", "Nb header lines : n", header text, tab-separated table
read_biologic_mpt = function(path, name = basename(path)) {
  L = iconv(readLines(path, warn = FALSE, encoding = "latin1"), "latin1", "UTF-8")
  n = as.integer(gsub("[^0-9]", "", L[2]))
  hdr = L[seq_len(n - 1)]; cols = strsplit(L[n], "\t")[[1]]; cols = cols[nzchar(trimws(cols))]
  if (length(L) <= n) stop(name, ": the file holds settings only, no data rows (technique: ", trimws(L[4]), ")")
  # trailing empty fields are dropped by strsplit, so short rows are padded with NA
  rows = strsplit(L[(n + 1):length(L)], "\t"); rows = rows[lengths(rows) >= 2]
  tab = as.data.frame(do.call(rbind, lapply(rows, `[`, seq_along(cols))), stringsAsFactors = FALSE); names(tab) = cols
  comma = any(grepl("^-?[0-9]+,[0-9]", tab[[1]][seq_len(min(5, nrow(tab)))])) || any(grepl("[0-9],[0-9]", unlist(tab[1, ])))
  kv = regmatches(hdr, regexec("^(\\S.*?)\\s{2,}(\\S.*)$", hdr)); kv = kv[lengths(kv) == 3]
  st = stats::setNames(lapply(kv, function(m) trimws(m[3])), vapply(kv, function(m) trimws(m[2]), ""))
  # several values when the technique has several sequences: the first is kept, as the scan rate of the first sweep
  first_tok = function(x) strsplit(trimws(x), "\\s+")[[1]][1]
  v = if (!is.null(st[["dE/dt"]])) num_col(first_tok(st[["dE/dt"]]), TRUE) * (if (grepl("^mV", first_tok(st[["dE/dt unit"]] %||% "mV/s"))) 1e-3 else 1) else NA
  if (isTRUE(v == 0)) v = NA
  # exports saved without the settings block have no technique line
  tech = trimws(hdr[4]); if (is.na(tech)) tech = "" else if (!nzchar(tech) || grepl(":", tech)) tech = trimws(hdr[grepl("^[A-Z][a-z]", hdr) & !grepl(":", hdr)][1] %||% "")
  params = list(file = name, technique = tech, settings = st, scan_rate_V_s = v, date = sub("^.*: ", "", grep("Acquisition started on", hdr, value = TRUE)[1] %||% ""))
  # impedance when Re(Z) is there and most rows have a frequency; Modulo Bat runs mix DC steps with a few
  # impedance points and stay as voltammetry
  fq = pick(tab, cols, "^freq/", comma)
  if (!is.null(fq) && any(grepl("^Re\\(Z\\)/", cols)) && mean(fq$v > 0, na.rm = TRUE) > 0.5) {
    f = fq$v; re = pick(tab, cols, "^Re\\(Z\\)/", comma)$v
    im = pick(tab, cols, "^-Im\\(Z\\)/", comma); im = if (!is.null(im)) -im$v else pick(tab, cols, "^Im\\(Z\\)/", comma)$v
    d = data.frame(freq_Hz = f, Z = complex(real = re, imaginary = im)); d = d[is.finite(d$freq_Hz) & d$freq_Hz > 0, ]
    return(list(file = name, kind = "eis", params = params, data = d, note = ""))
  }
  # battery runs (BCD) call the same potential Ecell
  E = pick(tab, cols, c("^Ewe/", "^<Ewe>/", "^Ecell/", "^Ewe-Ece/", "^control/V$"), comma); I = pick(tab, cols, c("^<I>/", "^I/"), comma)
  t = pick(tab, cols, "^time/", comma); Q = pick(tab, cols, c("^\\(Q-Qo\\)/", "^Q-Qo/"), comma); cyc = pick(tab, cols, "^cycle number$", comma, 1)
  d = data.frame(E_V = if (is.null(E)) NA else E$v, I_A = if (is.null(I)) NA else I$v, t_s = if (is.null(t)) NA else t$v - t$v[1],
                 Q_C = if (is.null(Q)) NA else Q$v, scan = if (is.null(cyc)) 1L else as.integer(cyc$v))
  d = add_segments(d[is.finite(d$t_s) | is.finite(d$E_V), ])
  list(file = name, kind = "voltammetry", params = params, data = d)
}

# Gamry Framework file (.DTA): "EXPLAIN", "TAG <technique>", parameter lines, then tables named CURVE, CURVEn or ZCURVE,
# each with a column-name row and a unit row that start with a tab
read_gamry_dta = function(path, name = basename(path)) {
  L = readLines(path, warn = FALSE, encoding = "latin1"); L = iconv(L, "latin1", "UTF-8")
  tag = sub("^TAG\t", "", grep("^TAG\t", L, value = TRUE)[1])
  par = strsplit(grep("^[A-Z][A-Z0-9_]*\t(QUANT|POTEN|IQUANT|SELECTOR|TOGGLE|LABEL|STRING|TWOPARAM)\t", L, value = TRUE), "\t")
  st = stats::setNames(lapply(par, function(x) x[3]), vapply(par, `[`, "", 1))
  v = if (!is.null(st[["SCANRATE"]])) as.numeric(st[["SCANRATE"]]) * (if (any(grepl("^SCANRATE\t.*mV/s", L))) 1e-3 else 1) else NA
  starts = grep("^[A-Z]*CURVE[0-9]*\tTABLE", L)
  tables = lapply(starts, function(s) {
    cols = strsplit(sub("^\t", "", L[s + 1]), "\t")[[1]]; units = strsplit(sub("^\t", "", L[s + 2]), "\t")[[1]]
    e = s + 3; while (e <= length(L) && startsWith(L[e], "\t")) e = e + 1
    rows = strsplit(sub("^\t", "", L[(s + 3):(e - 1)]), "\t")
    tab = as.data.frame(do.call(rbind, lapply(rows, `[`, seq_along(cols))), stringsAsFactors = FALSE); names(tab) = cols
    list(name = sub("\t.*$", "", L[s]), tab = tab, units = stats::setNames(units[seq_along(cols)], cols))
  })
  params = list(file = name, technique = tag, settings = st, scan_rate_V_s = v, date = st[["DATE"]] %||% "")
  # files saved with a European locale write decimal commas
  col = function(tb, k) { if (!k %in% names(tb$tab)) return(NULL); f = unit_scale(tb$units[[k]]); if (is.na(f)) f = 1
    x = tb$tab[[k]]; num_col(x, any(grepl("^-?[0-9]+,[0-9]", utils::head(x, 5)))) * f }
  z = Filter(function(tb) tb$name == "ZCURVE", tables)
  if (length(z)) { tb = z[[1]]
    d = data.frame(freq_Hz = col(tb, "Freq"), Z = complex(real = col(tb, "Zreal"), imaginary = col(tb, "Zimag")))
    return(list(file = name, kind = "eis", params = params, data = d[is.finite(d$freq_Hz) & d$freq_Hz > 0, ], note = "")) }
  cur = Filter(function(tb) grepl("^CURVE[0-9]*$", tb$name), tables)
  if (!length(cur)) cur = Filter(function(tb) tb$name != "ZCURVE" && any(c("Vf", "Im", "Voltage", "Current") %in% names(tb$tab)), tables)
  if (!length(cur)) stop(name, ": no potential or current table found (tables: ", paste(vapply(tables, `[[`, "", "name"), collapse = ", "), ")")
  d = do.call(rbind, lapply(seq_along(cur), function(i) { tb = cur[[i]]
    # pulse techniques: base potential and difference current; otherwise the measured potential and current
    E = col(tb, "Vstep") %||% col(tb, "Vf") %||% col(tb, "Vu") %||% col(tb, "Voltage"); I = col(tb, "Idif") %||% col(tb, "Im") %||% col(tb, "Current")
    n = nrow(tb$tab)
    data.frame(E_V = if (is.null(E)) rep(NA_real_, n) else E, I_A = if (is.null(I)) rep(NA_real_, n) else I,
               t_s = col(tb, "T") %||% rep(NA_real_, n), Q_C = col(tb, "Q") %||% rep(NA_real_, n), scan = i) }))
  # time restarts in every CURVE table of a CV: make it continuous
  if (length(cur) > 1 && !anyNA(d$t_s)) { last = tapply(d$t_s, d$scan, max); d$t_s = d$t_s + c(0, cumsum(last))[d$scan] }
  list(file = name, kind = "voltammetry", params = params, data = add_segments(d))
}

# Any other delimited text export with a header row: columns are found by their names and units
read_generic_text = function(path, name = basename(path)) {
  L = readLines(path, warn = FALSE, encoding = "UTF-8"); L = L[nzchar(trimws(L))]
  sep = names(which.max(c("\t" = sum(grepl("\t", L)), ";" = sum(grepl(";", L)), "," = sum(grepl(",", L)))))
  isnum = function(l) { x = trimws(strsplit(l, sep, fixed = TRUE)[[1]]); x = x[nzchar(x)]; length(x) >= 2 && mean(!is.na(suppressWarnings(as.numeric(sub(",", ".", x))))) > 0.8 }
  if (length(L) <= 5e4) {
    # the same test as isnum(), on all lines at once (line by line took 12 s for a 30000-row file): a line is data when
    # it has 2 or more non-empty fields and more than 80% of them are numbers
    toks = strsplit(L, sep, fixed = TRUE); id = rep(seq_along(toks), lengths(toks)); x = trimws(unlist(toks, use.names = FALSE))
    keep = nzchar(x); id = id[keep]; x = x[keep]
    okn = !is.na(suppressWarnings(as.numeric(sub(",", ".", x))))
    cnt = tabulate(id, nbins = length(L)); good = tabulate(id[okn], nbins = length(L))
    num = cnt >= 2 & good > 0.8 * cnt; first = which(num)[1]
    if (is.na(first) || first < 2) stop(name, ": no header row followed by numbers was found")
    cols = trimws(gsub('"', "", strsplit(L[first - 1], sep, fixed = TRUE)[[1]]))
    rows = toks[first:length(L)][num[first:length(L)]]
    tab = as.data.frame(do.call(rbind, lapply(rows, `[`, seq_along(cols))), stringsAsFactors = FALSE); names(tab) = cols
  } else {
    # long recordings (a 10 kHz trace has millions of rows): find the header in the first lines, then read the table
    # in one pass; checking every line on its own took minutes
    num = vapply(L[1:2000], isnum, TRUE); first = which(num)[1]
    if (is.na(first) || first < 2) stop(name, ": no header row followed by numbers was found")
    cols = trimws(gsub('"', "", strsplit(L[first - 1], sep, fixed = TRUE)[[1]]))
    tab = utils::read.table(text = L[first:length(L)], sep = sep, header = FALSE, colClasses = "character", fill = TRUE,
                            quote = "\"", comment.char = "", col.names = paste0("V", seq_len(max(length(cols), 2))), flush = TRUE)
    tab = tab[, seq_along(cols), drop = FALSE]; names(tab) = cols
    tab = tab[!is.na(suppressWarnings(as.numeric(sub(",", ".", tab[[1]])))), , drop = FALSE]   # rows of numbers only, as above
  }
  comma = sep != "," && any(grepl("[0-9],[0-9]", tab[[1]]))
  f = pick(tab, cols, c("^freq"), comma)
  if (!is.null(f)) return(NULL)                     # impedance: read_eis() handles it
  E = pick(tab, cols, c("WE\\(1\\)\\.Potential", "^Ewe", "Potential(?! applied)", "^E\\b", "^Voltage", "Potential applied"), comma, 1)
  I = pick(tab, cols, c("WE\\(1\\)\\.Current", "^<?I>?\\b", "Current"), comma, 1)
  t = pick(tab, cols, c("^Time", "^t\\b"), comma, 1); Q = pick(tab, cols, c("Charge", "^Q\\b"), comma, 1)
  sc = pick(tab, cols, c("^Scan$", "^Cycle"), comma, 1)
  if (is.null(E) && is.null(I)) stop(name, ": no potential or current column was recognised (columns: ", paste(cols, collapse = ", "), ")")
  n = nrow(tab)
  d = data.frame(E_V = E$v %||% rep(NA_real_, n), I_A = I$v %||% rep(NA_real_, n), t_s = t$v %||% rep(NA_real_, n), Q_C = Q$v %||% rep(NA_real_, n),
                 scan = if (is.null(sc)) 1L else as.integer(sc$v))
  v = NA
  if (!all(is.na(d$t_s)) && !all(is.na(d$E_V))) { k = which(diff(d$t_s) > 0 & is.finite(diff(d$E_V))); if (length(k) > 5) v = stats::median(abs(diff(d$E_V)[k] / diff(d$t_s)[k])) }
  list(file = name, kind = "voltammetry", params = list(file = name, technique = "text export", settings = list(columns = paste(cols, collapse = "; ")),
       scan_rate_V_s = if (is.finite(v) && v > 0) signif(v, 3) else NA), data = add_segments(d))
}

# which reader a file needs, from its first lines
detect_format = function(path) {
  if (is_pssession(path)) return("pssession")
  if (exists("is_mpr") && is_mpr(path)) return("mpr")
  if (exists("is_abf") && is_abf(path)) return("abf")
  L = readLines(path, n = 3, warn = FALSE)
  if (grepl("^EC-Lab ASCII FILE", L[1])) return("biologic")
  if (grepl("^EXPLAIN", L[1])) return("gamry")
  if (grepl("Plot Name:", L[1])) return("pine")
  # CHI starts with the date, the month written in full or shortened ("July 2, 2026", "Sept. 9, 2026")
  if (grepl("^[A-Z][a-z]+\\.? +[0-9]{1,2}, +[0-9]{4}", L[1])) return("chi")
  # numbers only, no header (CHI "data only" export): the CHI reader knows its column layouts
  if (grepl("^\\s*[-+]?[0-9.]+([eE][-+]?[0-9]+)?([\t,]\\s*[-+]?[0-9.]+([eE][-+]?[0-9]+)?)+\\s*$", L[1])) return("chi")
  "text"
}

# The instrument the user chose in the top bar ("auto" = recognise it from the file). A file that does not match the
# chosen instrument stops with a message saying what it looks like; "text" reads any delimited file with a header.
instrument_labels = c(auto = "Auto-detect", chi = "CH Instruments", pssession = "PalmSens", biologic = "BioLogic EC-Lab",
                      gamry = "Gamry", pine = "Pine AfterMath", abf = "Axon pCLAMP (.abf)", text = "Metrohm Autolab or other text/CSV")
instrument_format = function(path, name, instrument = "auto") {
  det = detect_format(path)
  fam = c(chi = "chi", pssession = "pssession", mpr = "biologic", biologic = "biologic", gamry = "gamry", pine = "pine", abf = "abf", text = "text")[[det]]
  if (is.null(instrument) || instrument == "auto" || instrument == fam) return(det)
  if (instrument == "text" && !det %in% c("pssession", "mpr", "abf")) return("text")
  stop(sprintf("%s does not look like a %s file (it looks like %s). Choose Auto-detect, or the instrument that recorded it.",
               name, instrument_labels[[instrument]], instrument_labels[[fam]]))
}

# Slide deck (PowerPoint, built with the officer package) and PDF of an ElectroFast analysis: a title slide, the
# settings, then for every tab with data its summary, plots (one per slide) and tables (split over slides
# when long). The same parts feed the HTML report, so both always show the same results.

# The deck follows the laboratory's own report decks (EtOH fall report 2, 21 Oct 2026): 16:9 white slides in Calibri
# with dark text, a title slide listing the cell, a main-points slide, then one slide per plot with the plot large
# and centred and the result as bullets under it. Every slide is a blank layout with text boxes at fixed positions,
# so the deck looks the same in PowerPoint, WPS and LibreOffice.
pptx_ink = "#111111"
pptx_par = function(txt, size, bold = FALSE, after = 6)
  officer::fpar(officer::ftext(txt, officer::fp_text(font.size = size, bold = bold, color = pptx_ink, font.family = "Calibri")),
                fp_p = officer::fp_par(padding.bottom = after))
pptx_box = function(doc, paras, left, top, width, height)
  officer::ph_with(doc, do.call(officer::block_list, paras), location = officer::ph_location(left = left, top = top, width = width, height = height))
pptx_bullets = function(lines, size) lapply(as.character(lines), function(l) pptx_par(paste0("•  ", l), size))
# rough number of printed lines, to decide what fits: Calibri averages about 0.5 em per character
pptx_lines = function(lines, size, width = 12) sum(ceiling(nchar(as.character(lines)) / (width * 72 / (0.5 * size))))
pptx_new = function(doc, title) {
  doc = officer::add_slide(doc, layout = "Blank", master = "Office Theme")
  pptx_box(doc, list(pptx_par(title, 24, bold = TRUE, after = 0)), 0.6, 0.25, 12.1, 0.8)
}
pptx_text = function(doc, title, lines) {
  # 15 pt bullets, as on the text slides of the report decks; long lists continue on a second slide
  per = 16; groups = list(character(0)); used = 0
  for (l in as.character(lines)) { n = pptx_lines(l, 15)
    if (used + n > per && length(groups[[length(groups)]])) { groups[[length(groups) + 1]] = character(0); used = 0 }
    groups[[length(groups)]] = c(groups[[length(groups)]], l); used = used + n }
  for (k in seq_along(groups)) {
    doc = pptx_new(doc, if (length(groups) > 1) sprintf("%s (%d of %d)", title, k, length(groups)) else title)
    doc = pptx_box(doc, pptx_bullets(groups[[k]], 15), 0.7, 1.2, 12, 5.8)
  }
  doc
}
pptx_plot = function(doc, title, g, caption = NULL) {
  f = tempfile(fileext = ".png"); ggplot2::ggsave(f, g, width = 10, height = 5, dpi = 200)
  doc = pptx_new(doc, title)
  doc = officer::ph_with(doc, officer::external_img(f, width = 10, height = 5), location = officer::ph_location(left = 1.67, top = 1.2, width = 10, height = 5))
  if (length(caption)) doc = pptx_box(doc, pptx_bullets(caption, 13), 0.6, 6.3, 12.1, 1.1)
  doc
}
pptx_table = function(doc, title, d, rows_per_slide = 12, max_cols = 8, caption = NULL) {
  d = as.data.frame(d); if (exists("nice_names")) names(d) = nice_names(names(d))
  if (ncol(d) > max_cols) d = d[, seq_len(max_cols)]
  d[] = lapply(d, function(v) if (is.numeric(v)) format(signif(v, 4)) else as.character(v))
  chunks = split(seq_len(nrow(d)), ceiling(seq_len(nrow(d)) / rows_per_slide))
  for (k in seq_along(chunks)) {
    doc = pptx_new(doc, if (length(chunks) > 1) sprintf("%s (%d of %d)", title, k, length(chunks)) else title)
    doc = officer::ph_with(doc, d[chunks[[k]], , drop = FALSE], alignment = rep("l", ncol(d)), location = officer::ph_location(left = 0.6, top = 1.2, width = 12.1, height = 0.3 * (length(chunks[[k]]) + 1)))
    # the result goes under the table on the first slide, as in the report decks
    if (k == 1 && length(caption)) doc = pptx_box(doc, pptx_bullets(caption, 15), 0.7, 1.2 + 0.3 * (length(chunks[[k]]) + 1) + 0.4, 12, 7.1 - (1.6 + 0.3 * (length(chunks[[k]]) + 1)))
  }
  doc
}
# A section: list(title, text, plots = named list of ggplots, tables = named list of data frames). Its text goes under
# the first plot (or the first table when there is no plot) when it fits there, and on a slide of its own otherwise.
pptx_section = function(doc, s) {
  txt = as.character(s$text); first_tab = if (length(s$tables)) nrow(as.data.frame(s$tables[[1]])) else Inf
  under_plot = length(txt) && length(s$plots) && pptx_lines(txt, 13) <= 4
  under_tab = length(txt) && !length(s$plots) && first_tab <= 8 && pptx_lines(txt, 15) <= 14 - first_tab
  if (length(txt) && !under_plot && !under_tab) doc = pptx_text(doc, s$title, txt)
  for (i in seq_along(s$plots)) doc = pptx_plot(doc, paste0(s$title, ": ", names(s$plots)[i]), s$plots[[i]], if (i == 1 && under_plot) txt)
  for (i in seq_along(s$tables)) doc = pptx_table(doc, paste0(s$title, ": ", names(s$tables)[i]), s$tables[[i]], caption = if (i == 1 && under_tab) txt)
  doc
}
# Main points: the summary lines of every section, under the section's name
pptx_main_points = function(doc, sections) {
  s = Filter(function(x) length(x$text) > 0, sections); if (!length(s)) return(doc)
  pages = list(list()); used = 0
  for (x in s) { n = 1 + pptx_lines(x$text, 15)
    if (used + n > 16 && length(pages[[length(pages)]])) { pages[[length(pages) + 1]] = list(); used = 0 }
    pages[[length(pages)]] = c(pages[[length(pages)]], list(pptx_par(x$title, 15, bold = TRUE, after = 2)), pptx_bullets(x$text, 15)); used = used + n }
  for (k in seq_along(pages)) {
    doc = pptx_new(doc, if (length(pages) > 1) sprintf("Main points (%d of %d)", k, length(pages)) else "Main points")
    doc = pptx_box(doc, pages[[k]], 0.7, 1.2, 12, 5.8)
  }
  doc
}
# details: named character vector for the title slide (for example Electrolyte, Working electrode); empty entries are left out
build_pptx = function(file, title, author, settings, sections, details = NULL) {
  tpl = "report/electrofast_slides_16x9.pptx"
  doc = if (file.exists(tpl)) officer::read_pptx(tpl) else officer::read_pptx()
  details = details[nzchar(trimws(details))]
  doc = officer::add_slide(doc, layout = "Blank", master = "Office Theme")
  lines = c(if (nzchar(author)) author, if (length(details)) paste0(names(details), ": ", details), paste("Date:", format(Sys.Date(), "%m/%d/%Y")), "Made with ElectroFast")
  doc = pptx_box(doc, c(list(pptx_par(title, 26, bold = TRUE)), lapply(lines, pptx_par, size = 26)), 0.8, 2.0, 11.7, 4.1)
  doc = pptx_main_points(doc, sections)
  for (s in sections) doc = pptx_section(doc, s)
  if (length(settings)) doc = pptx_table(doc, "Settings and files used", data.frame(Setting = names(settings), Value = vapply(settings, function(v) paste(v, collapse = ", "), "")))
  print(doc, target = file)
  pptx_table_font(file)
  invisible(file)
}
# officer writes table runs without run properties, so they take PowerPoint's 18 pt default. Give each table run
# 13 pt Calibri, as in the report decks (the header row stays bold through the table style).
pptx_table_font = function(file) {
  file = normalizePath(file); d = tempfile(); utils::unzip(file, exdir = d)
  for (f in list.files(file.path(d, "ppt", "slides"), "[.]xml$", full.names = TRUE)) {
    x = paste(readLines(f, warn = FALSE, encoding = "UTF-8"), collapse = "\n")
    if (!grepl("<a:tbl>", x, fixed = TRUE)) next
    m = gregexpr("(?s)<a:tbl>.*?</a:tbl>", x, perl = TRUE)
    regmatches(x, m) = list(gsub("<a:r>([[:space:]]*)<a:t(/?)>", "<a:r><a:rPr lang=\"en-US\" sz=\"1300\" dirty=\"0\"><a:latin typeface=\"Calibri\"/></a:rPr>\\1<a:t\\2>",
                                 regmatches(x, m)[[1]], perl = TRUE))
    writeLines(enc2utf8(x), f, useBytes = TRUE)
  }
  unlink(file); old = setwd(d); on.exit(setwd(old))
  zip::zipr(file, list.files(".", all.files = TRUE, no.. = TRUE))
}

# The same sections as a PDF (landscape Letter pages, base PDF device): a title page, a page of text for each
# section, one plot per page, and tables split over pages. No LaTeX or browser is needed (Cairo PDF device), so it also works
# on shinyapps.io.
pdf_page_text = function(title, lines, size = 11) {
  grid::grid.newpage()
  grid::grid.text(title, x = 0.05, y = 0.94, just = "left", gp = grid::gpar(fontsize = 18, fontface = "bold"))
  if (length(lines)) {
    w = unlist(lapply(as.character(lines), function(l) c(strwrap(l, 115, prefix = "", initial = "• ", exdent = 2), "")))
    grid::grid.text(paste(w, collapse = "\n"), x = 0.05, y = 0.86, just = c("left", "top"), gp = grid::gpar(fontsize = size, lineheight = 1.15))
  }
}
pdf_page_plot = function(title, g) {
  grid::grid.newpage()
  grid::grid.text(title, x = 0.05, y = 0.95, just = "left", gp = grid::gpar(fontsize = 15, fontface = "bold"))
  print(g, vp = grid::viewport(x = 0.5, y = 0.46, width = 0.92, height = 0.86))
}
pdf_page_table = function(title, d, rows_per_page = 16, max_cols = 9) {
  d = as.data.frame(d); if (exists("nice_names")) names(d) = nice_names(names(d)); if (ncol(d) > max_cols) d = d[, seq_len(max_cols)]
  d[] = lapply(d, function(v) if (is.numeric(v)) format(signif(v, 4)) else substr(as.character(v), 1, 45))
  chunks = split(seq_len(nrow(d)), ceiling(seq_len(nrow(d)) / rows_per_page))
  for (k in seq_along(chunks)) {
    grid::grid.newpage()
    grid::grid.text(if (length(chunks) > 1) sprintf("%s (%d of %d)", title, k, length(chunks)) else title, x = 0.05, y = 0.95, just = "left", gp = grid::gpar(fontsize = 15, fontface = "bold"))
    tg = gridExtra::tableGrob(d[chunks[[k]], , drop = FALSE], rows = NULL, theme = gridExtra::ttheme_minimal(base_size = 10))
    h_in = sum(grid::convertHeight(tg$heights, "in", valueOnly = TRUE)); w_in = sum(grid::convertWidth(tg$widths, "in", valueOnly = TRUE))
    grid::pushViewport(grid::viewport(x = 0.5, y = grid::unit(0.88, "npc"), just = c("centre", "top"), height = grid::unit(h_in, "in"), width = grid::unit(w_in, "in")))
    grid::grid.draw(tg); grid::popViewport()
  }
}
# PDF device for every PDF the app writes. On Windows the default sans font (Arial) has no subscript digits, so H₂SO₄
# printed with boxes; Segoe UI has them. Elsewhere the system default font is kept (fontconfig finds a font that has them).
echem_pdf = function(...) if (.Platform$OS.type == "windows") grDevices::cairo_pdf(..., family = "Segoe UI") else grDevices::cairo_pdf(...)

build_pdf = function(file, title, author, settings, sections) {
  echem_pdf(file, width = 11, height = 8.5, onefile = TRUE)
  on.exit(grDevices::dev.off())
  grid::grid.newpage()
  grid::grid.text(title, y = 0.6, gp = grid::gpar(fontsize = 26, fontface = "bold"))
  grid::grid.text(paste(c(if (nzchar(author)) author, format(Sys.time(), "%d %B %Y"), "Made with ElectroFast"), collapse = "\n"), y = 0.42, gp = grid::gpar(fontsize = 13, col = "grey30"))
  if (length(settings)) pdf_page_table("Settings", data.frame(Setting = names(settings), Value = vapply(settings, function(v) paste(v, collapse = ", "), "")))
  for (s in sections) {
    pdf_page_text(s$title, s$text)
    for (n in names(s$plots)) pdf_page_plot(paste0(s$title, ": ", n), s$plots[[n]])
    for (n in names(s$tables)) pdf_page_table(paste0(s$title, ": ", n), s$tables[[n]])
  }
  invisible(file)
}

# The same sections as one HTML file built directly in R. Used where Pandoc is not available (the browser version
# of the app, Shinylive), so rmarkdown cannot render: plots are embedded as PNG images and tables as HTML tables.
html_table = function(d) {
  d = as.data.frame(d); if (exists("nice_names")) names(d) = nice_names(names(d)); d[] = lapply(d, function(v) if (is.numeric(v)) format(signif(v, 4)) else as.character(v))
  htmltools::tags$table(htmltools::tags$thead(htmltools::tags$tr(lapply(names(d), htmltools::tags$th))),
    htmltools::tags$tbody(lapply(seq_len(nrow(d)), function(i) htmltools::tags$tr(lapply(d[i, ], htmltools::tags$td)))))
}
html_plot = function(g) {
  f = tempfile(fileext = ".png"); ggplot2::ggsave(f, g, width = 9, height = 5.2, dpi = 150)
  htmltools::tags$img(src = paste0("data:image/png;base64,", jsonlite::base64_enc(readBin(f, "raw", file.size(f)))), style = "max-width:100%")
}
build_html = function(file, title, author, settings, sections) {
  # the section list sits on the left and stays in view while scrolling, as in the Rmd report; on a narrow screen it goes on top
  css = "body{font-family:'Source Sans 3',Arial,sans-serif;max-width:1280px;margin:24px auto;padding:0 16px;color:#1f2933;display:grid;grid-template-columns:230px minmax(0,1fr);gap:32px}
    nav{position:sticky;top:16px;align-self:start;max-height:calc(100vh - 32px);overflow-y:auto;border:1px solid #d0d7de;border-radius:4px;padding:8px 0;font-size:14px}
    nav ul{list-style:none;margin:0;padding:0} nav a{display:block;padding:5px 14px;color:#1f2933;text-decoration:none} nav a:hover{background:#f5f7fa;color:#0b5cad}
    main{min-width:0} h1{margin:0 0 4px} h2{border-top:1px solid #d0d7de;padding-top:16px;margin-top:32px} .meta{color:#52606d}
    table{border-collapse:collapse;margin:8px 0 20px;font-size:14px;display:block;overflow-x:auto} th,td{border-bottom:1px solid #e4e7eb;padding:4px 10px;text-align:left}
    th{background:#f5f7fa} img{max-width:100%}
    @media (max-width:800px){body{display:block} nav{position:static;max-height:none;margin-bottom:16px}}"
  ids = sprintf("s%d", seq_along(sections))
  # the head is written as text: htmltools drops a tags$head() placed inside tags$html() when it renders
  nav_items = c(if (length(settings)) list(c("settings", "Settings")), lapply(seq_along(sections), function(i) c(ids[i], sections[[i]]$title)))
  body = htmltools::tags$body(
    htmltools::tags$nav(htmltools::tags$ul(lapply(nav_items, function(x) htmltools::tags$li(htmltools::tags$a(href = paste0("#", x[1]), x[2]))))),
    htmltools::tags$main(
      htmltools::tags$h1(title),
      htmltools::tags$p(class = "meta", paste(c(if (nzchar(author)) author, format(Sys.time(), "%d %B %Y"), "Made with ElectroFast"), collapse = " | ")),
      if (length(settings)) list(htmltools::tags$h2(id = "settings", "Settings"), html_table(data.frame(Setting = names(settings), Value = vapply(settings, function(v) paste(v, collapse = ", "), ""), check.names = FALSE))),
      lapply(seq_along(sections), function(i) { s = sections[[i]]
        list(htmltools::tags$h2(id = ids[i], s$title),
             if (length(s$text)) htmltools::tags$ul(lapply(as.character(s$text), htmltools::tags$li)),
             lapply(names(s$plots), function(n) list(htmltools::tags$h3(n), html_plot(s$plots[[n]]))),
             lapply(names(s$tables), function(n) list(htmltools::tags$h3(n), html_table(s$tables[[n]])))) })))
  writeLines(c("<!DOCTYPE html>", "<html lang=\"en\">", "<head>", "<meta charset=\"utf-8\">", paste0("<title>", htmltools::htmlEscape(title), "</title>"),
               paste0("<style>", css, "</style>"), "</head>", as.character(body), "</html>"), file, useBytes = TRUE)
  invisible(file)
}

// Keeps the user's work if the page is closed by mistake. The files and settings are saved in this browser only
// (IndexedDB and localStorage on this computer); nothing is sent to the server. Closing the tab after loading a file
// asks for confirmation, and on the next visit a bar offers to restore the saved session or discard it.
(function () {
  const KEY = "electrofast_session_v1", DB = "electrofast_files", STORE = "files";
  let dirty = false, restoring = false;

  function openDB() {
    return new Promise((res, rej) => {
      const r = indexedDB.open(DB, 1);
      r.onupgradeneeded = () => r.result.createObjectStore(STORE);
      r.onsuccess = () => res(r.result); r.onerror = () => rej(r.error);
    });
  }
  function tx(db, mode, fn) {
    return new Promise((res, rej) => { const t = db.transaction(STORE, mode); const out = fn(t.objectStore(STORE));
      t.oncomplete = () => res(out && out.result !== undefined ? out.result : undefined); t.onerror = () => rej(t.error); });
  }
  async function putFiles(id, files) {
    const arr = [];
    for (const f of files) arr.push({ name: f.name, type: f.type, data: await f.arrayBuffer() });
    const db = await openDB(); await tx(db, "readwrite", s => s.put(arr, id));
  }
  async function getFiles(id) { const db = await openDB(); return tx(db, "readonly", s => s.get(id)); }
  async function clearAll() {
    try { localStorage.removeItem(KEY); } catch (e) {}
    try { const db = await openDB(); await tx(db, "readwrite", s => s.clear()); } catch (e) {}
  }
  function loadState() { try { return JSON.parse(localStorage.getItem(KEY)) || null; } catch (e) { return null; } }
  function saveState(st) { try { localStorage.setItem(KEY, JSON.stringify(st)); } catch (e) {} }

  // inputs that are events or table internals, not settings
  const skip = id => !id || id.startsWith(".clientdata") || /_cell_edit$|_rows_|_cells_|_search|_state$|_columns_selected$/.test(id);

  // settings: every change is saved
  $(document).on("shiny:inputchanged", function (ev) {
    if (restoring || skip(ev.name)) return;
    const el = document.getElementById(ev.name); if (!el) return;
    if (el.type === "file" || el.classList.contains("action-button") || el.tagName === "BUTTON") return;
    const st = loadState() || { inputs: {}, files: [] };
    st.inputs[ev.name] = ev.value; st.saved = new Date().toISOString(); saveState(st);
  });

  // files: saved when chosen
  $(document).on("change", "input[type=file]", async function () {
    if (restoring || !this.id || !this.files.length) return;
    dirty = true;
    try {
      await putFiles(this.id, this.files);
      const st = loadState() || { inputs: {}, files: [] };
      if (!st.files.includes(this.id)) st.files.push(this.id);
      st.saved = new Date().toISOString(); saveState(st);
    } catch (e) { console.warn("ElectroFast: could not save the file in this browser", e); }
  });

  // warning before the page is closed or reloaded with work in it
  window.addEventListener("beforeunload", function (e) { if (dirty) { e.preventDefault(); e.returnValue = ""; return ""; } });

  function waitForUpload(id, ms) {
    return new Promise(res => {
      const h = ev => { if (ev.name === id) { $(document).off("shiny:inputchanged", h); res(true); } };
      $(document).on("shiny:inputchanged", h); setTimeout(() => { $(document).off("shiny:inputchanged", h); res(false); }, ms);
    });
  }

  async function restore(st) {
    restoring = true;
    // files first (they set some choices automatically), then the saved settings on top
    for (const id of st.files || []) {
      const el = document.getElementById(id); const saved = await getFiles(id);
      if (!el || !saved || !saved.length) continue;
      const dt = new DataTransfer();
      for (const f of saved) dt.items.add(new File([f.data], f.name, { type: f.type }));
      el.files = dt.files; const done = waitForUpload(id, 60000);
      el.dispatchEvent(new Event("change", { bubbles: true })); await done;
    }
    for (const [id, val] of Object.entries(st.inputs || {})) {
      const el = document.getElementById(id); if (!el) continue;
      const b = $(el).data("shiny-input-binding"); if (!b || !b.receiveMessage) continue;
      try { b.receiveMessage(el, { value: val }); } catch (e) {}
    }
    restoring = false; dirty = (st.files || []).length > 0;
    // save the restored session again, so a second accidental close keeps it too; restored settings win over the
    // defaults recorded while the page was loading, and the files are still in this browser's database
    const cur = loadState() || { inputs: {}, files: [] };
    saveState({ inputs: Object.assign({}, cur.inputs, st.inputs), files: Array.from(new Set([...(cur.files || []), ...(st.files || [])])),
                saved: new Date().toISOString() });
  }

  function bar(st) {
    const when = st.saved ? new Date(st.saved).toLocaleString() : "earlier";
    const n = (st.files || []).length;
    const div = document.createElement("div");
    div.id = "electrofast-restore-bar";
    div.style.cssText = "position:fixed;left:0;right:0;bottom:0;z-index:2000;background:#1F2328;color:#fff;padding:10px 18px;" +
                        "display:flex;gap:12px;align-items:center;flex-wrap:wrap;font-size:0.92rem;";
    div.innerHTML = "<span>A previous session (" + n + " file input" + (n === 1 ? "" : "s") + ", saved " + when +
      ") is kept in this browser on this computer only.</span>" +
      "<button class='btn btn-sm btn-light' id='electrofast-restore'>Restore previous session</button>" +
      "<button class='btn btn-sm btn-outline-light' id='electrofast-discard'>Discard</button>";
    document.body.appendChild(div);
    // either choice removes the copy kept aside when the page opened
    const dropPending = () => { try { localStorage.removeItem(KEY + "_pending"); } catch (e) {} };
    document.getElementById("electrofast-restore").onclick = async () => { div.remove(); await restore(st); dropPending(); };
    document.getElementById("electrofast-discard").onclick = async () => { div.remove(); await clearAll(); dropPending(); };
  }

  $(document).one("shiny:connected", function () {
    const st = loadState();
    if (st && ((st.files && st.files.length) || Object.keys(st.inputs || {}).length)) {
      // keep the old copy aside until the user decides, so new changes do not overwrite it
      try { localStorage.setItem(KEY + "_pending", JSON.stringify(st)); localStorage.removeItem(KEY); } catch (e) {}
      if (st.files && st.files.length) bar(st); else { try { localStorage.removeItem(KEY + "_pending"); } catch (e) {} }
    }
  });
})();
